<!DOCTYPE html>
<html>
<head>
  <title>Sorting Visualizer</title>
  <style>
    body { background-color: #1e1e1e; color: #fff; font-family: sans-serif;}
    #container { display: flex; flex-direction: column; align-items: center; margin-top: 20px; }
    #bars { display: flex; width: 500px; height: 300px; border: 1px solid #444; overflow: hidden;}
    .bar { height: auto; min-height: 20px; background-color: steelblue; margin: 2px; box-shadow: 2px 2px 5px rgba(0,0,0,0.3); transition: height 0.3s ease;}
    button { padding: 10px 20px; font-size: 16px; background-color: #333; color: white; border: none; cursor: pointer; margin: 5px;}
  </style>
</head>
<body>
  <div id="container">
    <h1>Sorting Visualizer</h1>
    <div id="bars"></div>
    <div>
      <button id="sort">Sort</button>
      <button id="shuffle">Shuffle</button>
      <button id="reset">Reset</button>
    </div>
  </div>

  <script>
    const arrayLength = 10;
    let arr = Array.from({ length: arrayLength }, () => Math.floor(Math.random() * 100)); // Initial array
    const barsContainer = document.getElementById('bars');
    const barElements = [];

    function renderBars() {
      barsContainer.innerHTML = '';
      barElements.forEach(barElement => barsContainer.appendChild(barElement));
    }


    window.viz = {
      array: () => arr,
      setArray: (a) => {
        arr = [...a];
        renderBars();
      },
      sortStep: () => {
        if (isSorted()) {
          return true;
        }

        // Bubble Sort implementation for animation
        for (let i = 0; i < arr.length - 1; i++) {
          for (let j = 0; j < arr.length - 1 - i; j++) {
            if (arr[j] > arr[j + 1]) {
              // Swap elements
              const temp = arr[j];
              arr[j] = arr[j + 1];
              arr[j + 1] = temp;

              // Update bar heights after each step
              renderBars();


              return false; // Indicate that a step was taken
            }
          }
        }
        return true;
      },
      sorted: () => {
        for (let i = 0; i < arr.length - 1; i++) {
          if (arr[i] > arr[i + 1]) {
            return false;
          }
        }
        return true;
      },
    };

    function createBar(value) {
      const bar = document.createElement('div');
      bar.classList.add('bar');
      bar.style.height = `${value}px`;
      barElements.push(bar);
      return bar;
    }


    function isSorted() {
        for (let i = 0; i < arr.length - 1; i++) {
            if (arr[i] > arr[i + 1]) {
                return false;
            }
        }
        return true;
    }

    document.getElementById('sort').addEventListener('click', () => {
      while (!window.viz.sortStep()) {
        // Optionally add a small delay for visual effect
        // window.setTimeout(() => {}, 10); // Example delay (not needed)
      }
    });

    document.getElementById('shuffle').addEventListener('click', () => {
      arr = Array.from({ length: arrayLength }, () => Math.floor(Math.random() * 100));
      renderBars();
    });

    document.getElementById('reset').addEventListener('click', () => {
      arr = Array.from({ length: arrayLength }, () => Math.floor(Math.random() * 100));
      renderBars();
    });

    // Initial render
    renderBars();
  </script>
</body>
</html>
